$string['bmc_hint_segments_purpose'] = 'Who the company creates value for and which customer segments are priorities.';
$string['bmc_hint_segments_questions'] = 'Who pays, decides and uses; what problem/goal the customer has; which segments drive revenue, margin, growth or strategic value; whether dangerous concentration exists.';
$string['bmc_hint_segments_mistake'] = 'Writing “all companies” or “everyone” without a segment and selection criteria.';
$string['bmc_hint_valueprop_purpose'] = 'Why the chosen customer prefers the company to alternatives and what outcome they receive.';
$string['bmc_hint_valueprop_questions'] = 'Customer + problem/goal + result + difference; product, service, brand, people and customer economics as one value package.';
$string['bmc_hint_valueprop_mistake'] = 'Listing product features instead of the customer outcome and reason to choose the company.';
$string['bmc_hint_relationships_purpose'] = 'How the company attracts, sells to, supports, retains, returns and develops the customer.';
$string['bmc_hint_relationships_questions'] = 'What the real customer cycle is; where owners, SLA, reviews and escalation rules exist; what should become a stable norm.';
$string['bmc_hint_relationships_mistake'] = 'Confusing relationships with channels: a channel answers “through what”, relationships answer “how the relationship and work cycle are built”.';
$string['bmc_hint_channels_purpose'] = 'Through which owned and partner channels the customer discovers, comes, buys and receives value.';
$string['bmc_hint_channels_questions'] = 'Which channels actually create demand and sales; what they contribute to revenue/margin; which should become repeatable and scalable.';
$string['bmc_hint_channels_mistake'] = 'Treating every marketing tool as a separate channel without understanding its role in demand, sales and value delivery.';
$string['bmc_hint_activities_purpose'] = 'Which activities are critical to creating the promised value and operating this specific business model.';
$string['bmc_hint_activities_questions'] = 'Product/service, marketing/sales, delivery/service, management and development; which capabilities are truly critical.';
$string['bmc_hint_activities_mistake'] = 'Listing every organizational function instead of the key capabilities of this business model.';
$string['bmc_hint_resources_purpose'] = 'Which resources and capabilities are critical to model resilience and development.';
$string['bmc_hint_resources_questions'] = 'Infrastructure, technology, finance/working capital, people, knowledge, brand, rights; where constraints and single points of failure exist.';
$string['bmc_hint_resources_mistake'] = 'Immediately writing “hire a person” instead of describing the capability or competence the company needs.';
$string['bmc_hint_partners_purpose'] = 'Who provides resources, capabilities or market access and reduces risk; what is better not done internally.';
$string['bmc_hint_partners_questions'] = 'Key suppliers, technology/channel partners, alliances, dependencies, alternatives and acceptable concentration.';
$string['bmc_hint_partners_mistake'] = 'Listing every counterparty instead of truly critical partners and dependencies.';
$string['bmc_hint_revenue_purpose'] = 'What customers/the market pay for and how revenue streams work.';
$string['bmc_hint_revenue_questions'] = 'Products, services, subscriptions, licenses, commissions; stream shares and recurrence, margin, concentration and the role of new sources.';
$string['bmc_hint_revenue_mistake'] = 'Writing only a target revenue number without explaining the streams and logic that create it.';
$string['bmc_hint_costs_purpose'] = 'Which costs are necessary to operate and develop the selected business model.';
$string['bmc_hint_costs_questions'] = 'People, procurement, logistics, rent, marketing, infrastructure, technology; which costs support target capabilities and REQ.';
$string['bmc_hint_costs_mistake'] = 'Designing an attractive target model without checking the cost of required capabilities and financial constraints.';

